// Package agekey owns the node's age identity (TRUST review 2026-09-30).
//
// Purpose: give the node its own age key pair so a coordinator can encrypt
// secret files to it, and report the recipient (age1...) in hello.
// Inputs:  the agent state directory and age-keygen from the node toolchain.
// Outputs: an Identity: the key file path and the recipient, or no recipient
// when age-keygen is absent (the node then receives no secret files).
// Constraints: <state>/age.key is 0600 and owned by the agent UID; it is
// generated by `age-keygen -o` run through internal/exec (the one process
// funnel), then written into place exclusively so a racing start cannot replace
// it;
// the agent never rotates the identity (a coordinator pins the recipient and
// closes on a change); the file is never placed in a job's environment or
// workspace, and only the recipient leaves this package. Like the node key it
// is readable by a job running as the same UID in user mode; UID or container
// isolation (P7-TRUST-09, P7-NODE-06) is what separates them.
package agekey

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"time"

	"github.com/nself-org/plugins/free/ci/internal/agent/nodekey"
	ciexec "github.com/nself-org/plugins/free/ci/internal/exec"
	"github.com/nself-org/plugins/free/ci/internal/model"
)

// FileName is the identity file under the state directory.
const FileName = "age.key"

// Binary is the key generator looked up on PATH.
const Binary = "age-keygen"

var (
	recipientLine = regexp.MustCompile(`(?m)^# public key: (age1[a-z0-9]+)\s*$`)
	attemptSafe   = regexp.MustCompile(`[^A-Za-z0-9]`)
)

// Identity is the node's age identity.
type Identity struct {
	// Path is the identity file ("" when none exists).
	Path string
	// Recipient is the age1... public key; nil when the node has no identity.
	Recipient *string
}

// Fact is the capability fact for the recipient: unknown when age-keygen was
// absent, so the node reports that it can receive no secret files.
func (i *Identity) Fact(observed time.Time) model.Fact[string] {
	if i == nil || i.Recipient == nil {
		return model.Fact[string]{Source: "self", ObservedAt: observed, Confidence: "unknown"}
	}
	r := *i.Recipient
	return model.Fact[string]{Value: &r, Source: "self", ObservedAt: observed, Confidence: "known"}
}

// LoadOrCreate returns the identity of stateDir, generating it on first start.
func LoadOrCreate(ctx context.Context, stateDir string) (*Identity, error) {
	if err := nodekey.EnsureDir(stateDir); err != nil {
		return nil, err
	}
	path := filepath.Join(stateDir, FileName)
	if id, err := load(path); !errors.Is(err, fs.ErrNotExist) {
		return id, err
	}
	bin, ok := lookPath(Binary)
	if !ok {
		return &Identity{}, nil
	}
	if err := generate(ctx, stateDir, path, bin); err != nil {
		return nil, err
	}
	return load(path)
}

func load(path string) (*Identity, error) {
	if err := nodekey.CheckPrivateFile(path); err != nil {
		return nil, err
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	m := recipientLine.FindSubmatch(raw)
	if m == nil {
		return nil, fmt.Errorf("%s has no public key comment line", path)
	}
	r := string(m[1])
	return &Identity{Path: path, Recipient: &r}, nil
}

// generate runs age-keygen into a private scratch directory and links the
// result to path; a concurrent winner's file is kept.
func generate(ctx context.Context, stateDir, path, bin string) error {
	scratch, err := os.MkdirTemp(stateDir, ".agekey-")
	if err != nil {
		return err
	}
	defer func() { _ = os.RemoveAll(scratch) }()
	out := filepath.Join(scratch, "key")
	var tag [6]byte
	if _, err := rand.Read(tag[:]); err != nil {
		return err
	}
	res := (&ciexec.Executor{Env: ciexec.AllowlistEnv{}}).Run(ctx, ciexec.JobSpec{
		AttemptID:     "agekey-" + attemptSafe.ReplaceAllString(hex.EncodeToString(tag[:]), ""),
		CoordinatorID: "agent",
		Command:       []string{bin, "-o", out},
		Home:          scratch,
	})
	if res.Err != nil || res.ExitCode != 0 {
		return fmt.Errorf("%s failed (exit %d): %v", Binary, res.ExitCode, res.Err)
	}
	if err := os.Chmod(out, 0o600); err != nil {
		return err
	}
	if _, err := load(out); err != nil {
		return err
	}
	raw, err := os.ReadFile(out)
	if err != nil {
		return err
	}
	if err := nodekey.WriteExclusive(path, raw); err != nil && !errors.Is(err, fs.ErrExist) {
		return err
	}
	return nil
}

// lookPath finds name in PATH without os/exec (the funnel is internal/exec).
func lookPath(name string) (string, bool) {
	for _, dir := range filepath.SplitList(os.Getenv("PATH")) {
		if dir == "" || !filepath.IsAbs(dir) {
			continue // a relative PATH entry would pick up a planted binary from the cwd
		}
		p := filepath.Join(dir, name)
		if info, err := os.Stat(p); err == nil && info.Mode().IsRegular() && info.Mode().Perm()&0o111 != 0 {
			return p, true
		}
	}
	return "", false
}
